//! Cargo-driven `shdocvw.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6e660000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe7f000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe7f000000u64)),
        o => panic!("shdocvw-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:c:cpprt", "engine:uuid", "engine:wine", "import:shell32", "import:user32", "import:gdi32", "import:ole32", "import:oleaut32", "import:ieframe", "import:shlwapi", "import:advapi32", "import:msvcrt", "import:comctl32", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista", "engine:delayimp_rust"],
        "x86_64" => &["engine:c:cpprt", "engine:uuid", "engine:wine", "import:shell32", "import:user32", "import:gdi32", "import:ole32", "import:oleaut32", "import:ieframe", "import:shlwapi", "import:advapi32", "import:msvcrt", "import:comctl32", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista", "engine:delayimp_rust"],
        "aarch64" => &["engine:c:cpprt", "engine:uuid", "engine:wine", "import:shell32", "import:user32", "import:gdi32", "import:ole32", "import:oleaut32", "import:ieframe", "import:shlwapi", "import:advapi32", "import:msvcrt", "import:comctl32", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/shdocvw",
        "dll/win32/shdocvw",
        "sdk/include/wine",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_SHDOCVW_",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .c_from_compile_db("shdocvw_shims", &["dll/win32/shdocvw/shdocvw_main.c", "dll/win32/shdocvw/shlinstobj.c"])
        .whole_c_objects("shdocvw_shims")
        .c_from_compile_db("shdocvw_sublib", &["dll/win32/shdocvw/CExplorerBand.cpp", "dll/win32/shdocvw/CFavBand.cpp", "dll/win32/shdocvw/CNSCBand.cpp", "dll/win32/shdocvw/mrulist.cpp", "dll/win32/shdocvw/objects.cpp", "dll/win32/shdocvw/utility.cpp", "dll/win32/shdocvw/winlist.cpp"])
        .whole_c_objects("shdocvw_sublib")
        .rc("dll/win32/shdocvw/shdocvw.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/shdocvw/shdocvw.spec", "shdocvw.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .delay_import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .delay_import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .delay_import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .delay_import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .delay_import_lib("dll/win32/ieframe/ieframe.spec", "ieframe.dll", "ieframe")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
